import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%80%90%E6%9B%B8%E7%B1%8D%E3%80%91%E6%96%B0%E3%81%97%E3%81%84%E4%BA%BA%E4%BD%93%E3%81%AE%E6%95%99%E7%A7%91%E6%9B%B8.html","title":"【書籍】新しい人体の教科書","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.61,"words":183},"filePathRelative":"【書籍】新しい人体の教科書.md"}`),a={name:`【書籍】新しい人体の教科書.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="【書籍】新しい人体の教科書" tabindex="-1"><a class="header-anchor" href="#【書籍】新しい人体の教科書"><span>【書籍】新しい人体の教科書</span></a></h1><p><a href="./生物学.html">生物学</a>, <a href="./生理学.html">生理学</a></p><p><a href="https://amzn.to/4aUBSIx" target="_blank" rel="noopener noreferrer">amazon: カラー図解　新しい人体の教科書　上</a></p><p>ブルーバックスの解剖学の教科書。この辺の本は電子書籍で読んでいる分にはブルーバックス感は全然無いが。</p><p>今の所全部読む気で買ったのでは無く、循環器系を見たい時にそこだけ見る、というように、 分野ごとの復習的な事のために読むつもりで買った。</p><h2 id="心臓のあたりを読んでいる-2026-03-02-月" tabindex="-1"><a class="header-anchor" href="#心臓のあたりを読んでいる-2026-03-02-月"><span>心臓のあたりを読んでいる 2026-03-02 (月)</span></a></h2><p>とりあえず心臓の働きを復習したくなったので最近読んでいる。 最初の細胞あたりは軽く復習したが、それ以外は飛ばして読んでいるが、割と独立して読める。 こういう読み方を期待していたので、その期待には答えている気がする。</p><p>臓器の構造的な話はまぁこんなもんでもいいかな、と思うが、もう少し細かい事を学びたい時にはやはり<a href="./生理学.html">生理学</a>の教科書などを学ぶ必要がありそう。</p><p>どこらへんが「新しい」のかは良く分からないのと、同じ図が何度も再掲されていて、たぶん見開きだとちょうどいいんだろうけれど、 電子版だと「なんで？」という気はちょっとしてしまう。まぁちょっと気をつければ特に困る訳では無い。</p><p>図解は割と分かりやすい。該当する臓器の図を見たいという目的で持っておいて良い本だと思った。</p><p>聴診器とか心電図とか普通の医者が診察する時に何をやっているのかの解説があってちょっと面白い。そういう理解が高まるのはいいね。</p>`,11)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};